def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def segments(n, separators):
        result = []
        start = 0
        for i in separators:
            if start < i:
                result.append((start, i))
            start = i + 1
        if start < n:
            result.append((start, n))
        return result

    rows = segments(h, sep_rows)
    cols = segments(w, sep_cols)
    blocks = []
    for r0, r1 in rows:
        for c0, c1 in cols:
            count = sum(grid[r][c] != background
                        for r in range(r0, r1) for c in range(c0, c1))
            blocks.append((count, r0, r1, c0, c1))

    _, sr0, sr1, sc0, sc1 = max(blocks)
    pattern = [row[sc0:sc1] for row in grid[sr0:sr1]]

    out = [row[:] for row in grid]
    for _, r0, r1, c0, c1 in blocks:
        for r in range(r0, r1):
            for c in range(c0, c1):
                out[r][c] = pattern[r - r0][c - c0]
    return out
